INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (1, N'course', N'COU-1349ebee849c4e98', N'', 2, N'{"title":"Design thinking, made practical","summary":"Turn a messy challenge into a clear, useful solution.","description":"Turn a messy challenge into a clear, useful solution. This practical course takes you from foundational ideas to a repeatable approach. Work through short lessons, apply what you learn and check your understanding with a final assessment.","category":"Design","level":"Beginner","image_url":"/course-1.svg","price":0,"currency":"USD","instructor":"Alex Morgan","instructors":["3"],"status":"published","kind":"course","ref":"COU-1349ebee849c4e98","version":2,"updated":1789430400,"created":1789430400,"owner":"","release":"REL-b8e24b383f3942dd"}');
