INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (3, N'lesson', N'LES-d7bd4c760c21428b', N'', 1, N'{"course":"COU-1349ebee849c4e98","title":"A useful starting point","module":"Foundations","position":0,"type":"article","body":"Start by writing down one problem you want to solve. Make it specific: who is affected, what happens, and why does it matter?\n\nA clear problem statement makes the next decision easier. Avoid jumping straight to solutions. Describe the current situation and the outcome you want.\n\nTry it: Write a one-sentence problem statement for a real situation in your work.","video_url":"","minutes":8,"required":true,"preview":true,"questions":[],"pass_percent":70,"max_attempts":3,"drip_days":0,"archived":false,"kind":"lesson","ref":"LES-d7bd4c760c21428b","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (4, N'audit', N'AUD-dcb5ee77d93b4959', N'', 1, N'{"entity":"LES-d7bd4c760c21428b","action":"lesson-saved","actor":"1","kind":"audit","ref":"AUD-dcb5ee77d93b4959","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (5, N'lesson', N'LES-92216c932ef2492c', N'', 1, N'{"course":"COU-1349ebee849c4e98","title":"Ask better questions","module":"Foundations","position":1,"type":"article","body":"Good questions create room for learning. Use open questions that invite examples, rather than questions that ask people to confirm your assumptions.\n\nAsk: Tell me about the last time this happened. What did you try? What made it difficult?\n\nPractice: Rewrite three yes/no questions as open questions.","video_url":"","minutes":10,"required":true,"preview":false,"questions":[],"pass_percent":70,"max_attempts":3,"drip_days":0,"archived":false,"kind":"lesson","ref":"LES-92216c932ef2492c","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
