INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (7, N'lesson', N'LES-1f6dab44c2874b1e', N'', 1, N'{"course":"COU-1349ebee849c4e98","title":"Make a small experiment","module":"In practice","position":2,"type":"article","body":"Choose a small, reversible experiment. Define what you expect to learn, the simplest way to test it, and a clear signal of success.\n\nKeep your first test small enough to complete in a day. Capture what you observed separately from what you think it means.\n\nPractice: Draft a simple test plan with a hypothesis, an action and a measurable result.","video_url":"","minutes":12,"required":true,"preview":false,"questions":[],"pass_percent":70,"max_attempts":3,"drip_days":0,"archived":false,"kind":"lesson","ref":"LES-1f6dab44c2874b1e","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
