INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (9, N'lesson', N'LES-384b42a9235346e8', N'', 1, N'{"course":"COU-1349ebee849c4e98","title":"Reflect and improve","module":"In practice","position":3,"type":"article","body":"Review your evidence before deciding what to do next. What surprised you? Which assumptions were supported? Which need another test?\n\nShare a concise learning summary with your team: what we tried, what happened, and what we recommend next.\n\nYour final activity: Create a one-page plan that applies the course ideas to a project you care about.","video_url":"","minutes":14,"required":true,"preview":false,"questions":[],"pass_percent":70,"max_attempts":3,"drip_days":0,"archived":false,"kind":"lesson","ref":"LES-384b42a9235346e8","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
