INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (11, N'lesson', N'LES-5a35dd3632b44897', N'', 1, N'{"course":"COU-1349ebee849c4e98","title":"Check your understanding","module":"Put it together","position":4,"type":"quiz","body":"","video_url":"","minutes":10,"required":true,"preview":false,"questions":[{"prompt":"What should you do before choosing a solution?","choices":["Define the problem and desired outcome","Build the largest possible project","Skip research"],"answer":0},{"prompt":"Which question encourages learning?","choices":["Do you agree with my plan?","Tell me about the last time this happened.","Is this good?"],"answer":1},{"prompt":"What makes a useful first experiment?","choices":["It tests every possible scenario","It is expensive and permanent","It is small, measurable and reversible"],"answer":2},{"prompt":"What should you do after a test?","choices":["Review evidence and decide the next step","Ignore unexpected results","Repeat without changing anything"],"answer":0}],"pass_percent":75,"max_attempts":3,"drip_days":0,"archived":false,"kind":"lesson","ref":"LES-5a35dd3632b44897","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
