INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (31, N'lesson', N'LES-1df991b9be9240c6', N'', 1, N'{"course":"COU-425b12ea074d455e","title":"A useful starting point","module":"Foundations","position":0,"type":"article","body":"Start by writing down one problem you want to solve. Make it specific: who is affected, what happens, and why does it matter?\n\nA clear problem statement makes the next decision easier. Avoid jumping straight to solutions. Describe the current situation and the outcome you want.\n\nTry it: Write a one-sentence problem statement for a real situation in your work.","video_url":"","minutes":8,"required":true,"preview":true,"questions":[],"pass_percent":70,"max_attempts":3,"drip_days":0,"archived":false,"kind":"lesson","ref":"LES-1df991b9be9240c6","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (32, N'audit', N'AUD-ccd43667887d4245', N'', 1, N'{"entity":"LES-1df991b9be9240c6","action":"lesson-saved","actor":"1","kind":"audit","ref":"AUD-ccd43667887d4245","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (33, N'lesson', N'LES-6640709330264f2e', N'', 1, N'{"course":"COU-425b12ea074d455e","title":"Ask better questions","module":"Foundations","position":1,"type":"article","body":"Good questions create room for learning. Use open questions that invite examples, rather than questions that ask people to confirm your assumptions.\n\nAsk: Tell me about the last time this happened. What did you try? What made it difficult?\n\nPractice: Rewrite three yes/no questions as open questions.","video_url":"","minutes":10,"required":true,"preview":false,"questions":[],"pass_percent":70,"max_attempts":3,"drip_days":0,"archived":false,"kind":"lesson","ref":"LES-6640709330264f2e","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (34, N'audit', N'AUD-4b5846ab5c894a7d', N'', 1, N'{"entity":"LES-6640709330264f2e","action":"lesson-saved","actor":"1","kind":"audit","ref":"AUD-4b5846ab5c894a7d","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (35, N'lesson', N'LES-8fb05fb74fa2485c', N'', 1, N'{"course":"COU-425b12ea074d455e","title":"Make a small experiment","module":"In practice","position":2,"type":"article","body":"Choose a small, reversible experiment. Define what you expect to learn, the simplest way to test it, and a clear signal of success.\n\nKeep your first test small enough to complete in a day. Capture what you observed separately from what you think it means.\n\nPractice: Draft a simple test plan with a hypothesis, an action and a measurable result.","video_url":"","minutes":12,"required":true,"preview":false,"questions":[],"pass_percent":70,"max_attempts":3,"drip_days":0,"archived":false,"kind":"lesson","ref":"LES-8fb05fb74fa2485c","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (36, N'audit', N'AUD-f8ebbdabc91840f6', N'', 1, N'{"entity":"LES-8fb05fb74fa2485c","action":"lesson-saved","actor":"1","kind":"audit","ref":"AUD-f8ebbdabc91840f6","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
INSERT INTO [entities] ([Id], [kind], [ref], [owner], [version], [data]) VALUES (37, N'lesson', N'LES-5ae50111428d46c6', N'', 1, N'{"course":"COU-425b12ea074d455e","title":"Reflect and improve","module":"In practice","position":3,"type":"article","body":"Review your evidence before deciding what to do next. What surprised you? Which assumptions were supported? Which need another test?\n\nShare a concise learning summary with your team: what we tried, what happened, and what we recommend next.\n\nYour final activity: Create a one-page plan that applies the course ideas to a project you care about.","video_url":"","minutes":14,"required":true,"preview":false,"questions":[],"pass_percent":70,"max_attempts":3,"drip_days":0,"archived":false,"kind":"lesson","ref":"LES-5ae50111428d46c6","version":1,"updated":1789430400,"created":1789430400,"owner":""}');
